-- slug único para el motor y el linkeo de planned_exercises
alter table public.exercises add column if not exists slug text;
create unique index if not exists exercises_slug_key on public.exercises (slug) where slug is not null;

on conflict (slug) where slug is not null do nothing;

-- alimentos seed: fuente única de la sección de presupuesto
create unique index if not exists foods_seed_name_key on public.foods (name) where source = 'seed';
alter table public.foods add column if not exists vegan boolean default true;
alter table public.foods add column if not exists vegetarian boolean default true;

on conflict (name) where source = 'seed' do nothing;
